--
-- Table structure for table `company`
--

CREATE TABLE `company` (
  `id` int(11) NOT NULL,
  `com_name` text NOT NULL,
  `is_active` tinyint(4) NOT NULL DEFAULT '1',
  `insert_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `address` text NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=test purpose,1=purchased',
  `com_head_id` int(11) NOT NULL DEFAULT '0',
  `daddress` text,
  `soft_charge` varchar(4) DEFAULT '0' COMMENT '0=monthly bill,otherwise per order bill',
  `sms_charge` varchar(4) DEFAULT NULL,
  `soft_type` tinyint(1) DEFAULT NULL COMMENT '1=online,2=offline',
  `security` text,
  `sms_service` tinyint(1) DEFAULT NULL COMMENT '1=allow sms,2=not allow sms',
  `measure_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=standard,1=normal',
  `api` text,
  `mobile_num` text,
  `sversion` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=current copy,1=old copy ',
  `factory_delivery` tinyint(1) NOT NULL DEFAULT '1',
  `customer_delivery` int(3) NOT NULL DEFAULT '7',
  `set_tax` varchar(11) NOT NULL DEFAULT '0',
  `ord_settings` tinyint(1) NOT NULL DEFAULT '0',
  `email` text,
  `design_set` tinyint(1) NOT NULL DEFAULT '0',
  `active_reference` tinyint(1) NOT NULL DEFAULT '0',
  `reference_amount` varchar(4) NOT NULL DEFAULT '0',
  `order_copy` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=previous + present due, 0=only present due',
  `backup` text COMMENT 'db backup batch file link',
  `is_stock` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=maintaining stock, 0=not maintaining stock',
  `owner_name` varchar(100) DEFAULT NULL,
  `sefty_stock` int(11) NOT NULL DEFAULT '0',
  `apply_selling_price` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=not apply selling price, 1=apply selling price',
  `fab_money_receipt_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=pos receipt,1=normal receipt',
  `order_sms` tinyint(1) NOT NULL DEFAULT '0',
  `item_receive_sms` tinyint(1) NOT NULL DEFAULT '0',
  `emp_payment_sms` tinyint(1) NOT NULL DEFAULT '0',
  `is_barcode` tinyint(1) NOT NULL DEFAULT '0',
  `daily_attendance` tinyint(1) NOT NULL DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

