CREATE TABLE `order_record` (
  `id` int(11) NOT NULL,
  `dsms_id` int(11) DEFAULT NULL,
  `com_id` int(11) NOT NULL,
  `item_id` int(11) NOT NULL,
  `order_number` varchar(12) NOT NULL,
  `master_id` int(11) DEFAULT '0',
  `karigor_id` int(11) DEFAULT '0',
  `order_date` date DEFAULT NULL,
  `delivery_date` varchar(25) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=temp_order,1=perma_ord,2=delete_order',
  `insert_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `insert_by` int(11) NOT NULL,
  `item_qty` int(6) NOT NULL,
  `group_id` tinyint(1) NOT NULL,
  `ptype` tinyint(1) DEFAULT NULL COMMENT '1=gent,2=lady',
  `online_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=local,1=transferred to online',
  `receive_qty` int(5) DEFAULT '0',
  `delivery_qty` int(5) NOT NULL DEFAULT '0',
  `design_cost` decimal(11,0) NOT NULL DEFAULT '0',
  `amount_cost` decimal(11,0) NOT NULL DEFAULT '0',
  `group_name` text,
  `maker` int(11) NOT NULL DEFAULT '0',
  `assign_date` varchar(25) DEFAULT NULL,
  `emp_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=master,2=karigor',
  `master_cutting_qty` int(11) NOT NULL DEFAULT '0',
  `master_assign_date` varchar(25) DEFAULT NULL,
  `master_emp_id` int(11) NOT NULL DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

