--
-- Table structure for table `point_tbl`
--

CREATE TABLE `point_tbl` (
  `id` int(11) NOT NULL,
  `cus_id` int(11) NOT NULL,
  `point` varchar(6) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `insert_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `com_id` int(11) NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Table structure for table `product`
--

CREATE TABLE `product` (
  `id` int(11) NOT NULL,
  `product_name` varchar(255) NOT NULL,
  `cus_price` int(11) DEFAULT NULL,
  `com_id` int(11) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0=delete,1=making item,2=fabrics item,3=item category',
  `insert_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `master_price` int(11) DEFAULT '0',
  `artisan_price` int(11) DEFAULT '0',
  `group_id` tinyint(1) DEFAULT NULL,
  `ptype` tinyint(1) DEFAULT NULL COMMENT '1=gents,2=lady',
  `steps` int(11) NOT NULL DEFAULT '0',
  `stock_qty` varchar(11) NOT NULL DEFAULT '0',
  `total_price` varchar(11) NOT NULL DEFAULT '0',
  `avg_price` varchar(11) NOT NULL DEFAULT '0',
  `purchase_price` varchar(10) NOT NULL DEFAULT '0',
  `uom` varchar(25) DEFAULT NULL,
  `item_code` varchar(50) DEFAULT NULL,
  `selling_price` varchar(11) NOT NULL DEFAULT '0',
  `last_update_date` varchar(25) DEFAULT NULL,
  `last_update_by` int(4) NOT NULL DEFAULT '0',
  `img_location` text,
  `brand` varchar(256) DEFAULT NULL,
  `description` text,
  `safety_stock` varchar(11) NOT NULL DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

