--
-- Table structure for table `purchase_sms`
--

CREATE TABLE `purchase_sms` (
  `id` int(11) NOT NULL,
  `com_id` int(11) NOT NULL,
  `purchase_sms_qty` int(11) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `insert_by` int(11) DEFAULT NULL,
  `insert_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `trxn` varchar(25) DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Table structure for table `rem_sms`
--

CREATE TABLE `rem_sms` (
  `id` int(11) NOT NULL,
  `com_id` int(11) NOT NULL,
  `rem_sms` int(11) NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Table structure for table `salary_transaction`
--

CREATE TABLE `salary_transaction` (
  `id` int(11) NOT NULL,
  `emp_id` int(11) NOT NULL DEFAULT '0',
  `emp_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=master, 2=karigor,3=staff',
  `salary_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=item wise,2=daily basis, 3=monthly basis',
  `emp_name` varchar(200) DEFAULT NULL,
  `emp_mobile` varchar(15) DEFAULT NULL,
  `insert_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `remarks` text,
  `actual_salary` varchar(16) NOT NULL DEFAULT '0',
  `deductted_salary` varchar(15) NOT NULL DEFAULT '0',
  `process_date` varchar(25) DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=salary earn, 1=salary payment',
  `insert_by` int(11) NOT NULL DEFAULT '0',
  `update_by` int(11) NOT NULL DEFAULT '0',
  `update_date` varchar(25) DEFAULT NULL,
  `update_remarks` text,
  `attendence_tbl_id` int(11) NOT NULL DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Table structure for table `sales_detail`
--

CREATE TABLE `sales_detail` (
  `id` int(11) NOT NULL,
  `com_id` int(11) NOT NULL,
  `pid` int(11) NOT NULL,
  `pqty` int(11) NOT NULL,
  `dsms_id` int(11) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1'
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

