-- Table structure for table `security`
--

CREATE TABLE `security` (
  `id` int(11) NOT NULL,
  `pin1` text NOT NULL,
  `pin2` text NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '0',
  `com_id` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

