--
-- Table structure for table `transaction`
--

CREATE TABLE `transaction` (
  `id` int(11) NOT NULL,
  `com_id` int(11) NOT NULL DEFAULT '0',
  `cus_id` int(11) NOT NULL DEFAULT '0',
  `amount` varchar(11) NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=due,1= payable',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `insert_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `remarks` text,
  `insert_by` int(11) DEFAULT '0',
  `transaction_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=due rdmt panel receive,2=fab receive tk',
  `accounting_id` int(11) NOT NULL DEFAULT '0',
