--
-- Table structure for table `user`
--

CREATE TABLE `user` (
  `id` int(11) NOT NULL,
  `com_id` int(11) NOT NULL,
  `user_name` varchar(255) NOT NULL,
  `mobile` varchar(15) NOT NULL,
  `log_user` varchar(50) DEFAULT NULL,
  `pass` varchar(50) DEFAULT NULL,
  `sms_qty` int(11) DEFAULT NULL,
  `user_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=super admin,2=admin,0=common user',
  `rem_sms` int(11) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `insert_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `trxn` varchar(25) DEFAULT NULL,
  `address` varchar(250) DEFAULT NULL,
  `emp_type` tinyint(1) DEFAULT NULL COMMENT '1=master, 2=karigor',
  `settings` tinyint(1) NOT NULL DEFAULT '1',
  `order_name` tinyint(1) NOT NULL DEFAULT '1',
  `pending` tinyint(1) NOT NULL DEFAULT '1',
  `urgent` tinyint(1) NOT NULL DEFAULT '1',
  `todays` tinyint(1) NOT NULL DEFAULT '1',
  `tomorrow` tinyint(1) NOT NULL DEFAULT '1',
  `n3d` tinyint(1) NOT NULL DEFAULT '1',
  `search` tinyint(1) NOT NULL DEFAULT '1',
  `archive` tinyint(1) NOT NULL DEFAULT '1',
  `mobile_num` tinyint(1) NOT NULL DEFAULT '1',
  `prints` tinyint(1) NOT NULL DEFAULT '1',
  `emp_address` text,
  `salary_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=item_wise,2=daily basis, 3= monthly basis',
  `salary` varchar(15) NOT NULL DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

